// Signature: int sched_yield(void);

// Cause the calling thread to relinquish the CPU.
// It is moved to the end of the queue for its
// current static priority level.

int status;

// Voluntarily give up the remainder of the time slice.
status = sched_yield();

if (status == 0) {
    // Successfully yielded CPU time.
} else {
    // System call failed (check errno).
    // Failure is highly rare.
}
